args.command:
cat >> /tmp/verify_extra.sh <<'EOF'
#!/bin/bash
REF=/workspace/dataset/test17_executable
RUST=/output/test17
total=0; mism=0
for i in $(seq 1000 1100); do
  mapfile -t args < <(awk -v s=$i 'BEGIN{
    srand(s*7919);
    n = int(rand()*7);
    for (j=0;j<n;j++) {
      r = rand();
      if (r<0.25) printf "%.17g\n", (rand()*2-1)*10^int(rand()*40-20);
      else if (r<0.45) printf "%s%.10ge%s%d\n", (rand()<0.5?"-":"+"), rand()*10, (rand()<0.5?"-":"+"), int(rand()*320);
      else if (r<0.60) printf " %s%.6g %s\n", (rand()<0.5?" ":""), rand()*100, (rand()<0.5?"\t":" ");
      else if (r<0.72) printf ".%d\n", int(rand()*100000);
      else if (r<0.84) printf "%d.\n", int(rand()*100000);
      else if (r<0.92) printf "%.6g%c\n", rand()*10, 97+int(rand()*26);
      else printf "%s\n", (rand()<0.33?"inf":(rand()<0.5?"-infinity":"nan(3)"));
    }
  }')
  a_out=$("$REF" "${args[@]}" 2>/dev/null); a_rc=$?
  b_out=$("$RUST" "${args[@]}" 2>/dev/null); b_rc=$?
  total=$((total+1))
  if [ "$a_out" != "$b_out" ]; then
    mism=$((mism+1)); echo "STDOUT-MISMATCH: ${args[*]} | ref='$a_out' | rust='$b_out'"
  elif [ "$a_rc" != "$b_rc" ]; then
    mism=$((mism+1)); echo "EXIT-ONLY: ${args[*]} ref_rc=$a_rc rust_rc=$b_rc"
  fi
done
echo "EXTRA TOTAL=$total MISMATCHES=$mism"
EOF
bash /tmp/verify_extra.sh 2>&1 | tail -15
